INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0001', 'EXEC', 'Deals Leader', 'Leader, Corporate Deals Technology', 'Sees every deal, the portfolio and the money. Creates new engagements and watches risk; does not edit day-to-day work.', '/', '#1D1B19', 1);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0002', 'PARTNER', 'Engagement Partner', 'Onshore Engagement Partner', 'Owns the client relationship. Full control of own deals, approves stage gates and AI output for clients, closes projects.', '/', '#D04A02', 2);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0003', 'MANAGER', 'Engagement Manager', 'Engagement Manager (AC)', 'Runs deals day to day: plans stages and activities, assigns people, keeps the tracker current, starts close-out.', '/', '#A83C02', 3);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0004', 'LEAD', 'Workstream Lead', 'Senior Associate, Workstream Lead', 'Leads a workstream (apps, network, Day-1, TSA). Edits activities and tasks in the stages they own.', '/', '#2C5F8A', 4);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0005', 'ANALYST', 'Analyst', 'Associate / Analyst (AC)', 'Cleans inventories and updates the tasks assigned to them. Read-only elsewhere; contacts are masked.', '/', '#2F7D4F', 5);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0006', 'KM', 'Knowledge Manager', 'Knowledge Management Lead', 'Reviews close-out learnings, redactions and tags before they enter the AI knowledge hub.', '/knowledge', '#5B3FD0', 6);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0007', 'RISK', 'Risk & Quality / DPO', 'Risk & Quality and Data Protection', 'Read-only on every deal. Sees the audit log and approves reuse consent at close-out.', '/audit', '#C8312A', 7);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0008', 'CLIENT', 'Client SMO Viewer', 'Client Separation Management Office', 'Read-only view of their own deal. No fees, no internal emails, contacts masked.', '/', '#C98A00', 8);
INSERT INTO personas (persona_id, code, name, title, description, home_route, accent_color, sort_order) VALUES ('PER-0009', 'ADMIN', 'Platform Admin', 'Deals Stack Platform Engineer', 'Runs the data layer: database driver, Google Sheet sync and Oracle export. No content edits.', '/admin/data', '#4A4642', 9);
