INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0001', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Stage Template', 'TSA exit', 'Financial Services & Payments', 'Diligence', 'Diligence playbook - Payments TSA exit (anonymised)', 'Find IT risks, costs and entanglement before the price is fixed. Worked well on a closed tsa exit in Financial Services & Payments.', '{"stage":{"name":"Diligence","description":"Find IT risks, costs and entanglement before the price is fixed.","gate_criteria":"Diligence report signed by the partner; red flags closed or accepted."},"activities":[{"name":"210-application inventory baseline","description":"Build one reconciled list of in-scope applications with owners, hosting and users.","priority":"High","tasks":[{"title":"Collect CMDB and EA tool extracts","priority":"Medium","day1_critical":"N","effort_hours":22},{"title":"Run duplicate and gap quality check","priority":"High","day1_critical":"N","effort_hours":38},{"title":"Confirm business and IT owners","priority":"Low","day1_critical":"N","effort_hours":24},{"title":"Tag Day-1 critical applications","priority":"Medium","day1_critical":"N","effort_hours":26},{"title":"Map applications to sites","priority":"Medium","day1_critical":"N","effort_hours":27},{"title":"Sign off baseline with client CIO","priority":"Medium","day1_critical":"N","effort_hours":18}]},{"name":"Data room IT review","description":"Read the seller IT files, contracts and org charts in the virtual data room.","priority":"Medium","tasks":[{"title":"Index data room IT folders","priority":"Low","day1_critical":"N","effort_hours":21},{"title":"Review master services agreements","priority":"Medium","day1_critical":"N","effort_hours":32},{"title":"Summarise IT org and headcount","priority":"High","day1_critical":"N","effort_hours":28},{"title":"Flag missing IT documents to seller","priority":"Medium","day1_critical":"N","effort_hours":17}]},{"name":"IT run-cost baseline","description":"Establish current IT run cost of the business being separated.","priority":"Low","tasks":[{"title":"Collect IT cost allocations","priority":"Medium","day1_critical":"N","effort_hours":11},{"title":"Split shared cost by usage","priority":"Medium","day1_critical":"N","effort_hours":36},{"title":"Estimate standalone run cost","priority":"Low","day1_critical":"N","effort_hours":26},{"title":"Review cost model with finance","priority":"Low","day1_critical":"N","effort_hours":24}]},{"name":"Cyber and licence red flags","description":"Security gaps and non-transferable licences that change price or plan.","priority":"High","tasks":[{"title":"Review licence assignment clauses","priority":"Medium","day1_critical":"N","effort_hours":13},{"title":"List licences needing vendor consent","priority":"Low","day1_critical":"N","effort_hours":38},{"title":"Check privileged access model","priority":"High","day1_critical":"N","effort_hours":39},{"title":"Assess cyber posture gaps","priority":"Medium","day1_critical":"N","effort_hours":27},{"title":"Brief partner on red flags","priority":"Medium","day1_critical":"N","effort_hours":37}]}]}', 'diligence,template,tsa exit', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 7, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0002', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Stage Template', 'TSA exit', 'Financial Services & Payments', 'Signing', 'Signing playbook - Payments TSA exit (anonymised)', 'Turn diligence into separation terms: blueprint, TSA catalogue, cost sharing, Day-1 scope. Worked well on a closed tsa exit in Financial Services & Payments.', '{"stage":{"name":"Signing","description":"Turn diligence into separation terms: blueprint, TSA catalogue, cost sharing, Day-1 scope.","gate_criteria":"Deal signed; Day-1 scope and TSA catalogue baselined."},"activities":[{"name":"One-time and stranded cost estimate","description":"Cost to separate and seller cost left behind.","priority":"High","tasks":[{"title":"Build one-time cost model","priority":"Medium","day1_critical":"N","effort_hours":31},{"title":"Estimate stranded IT cost","priority":"Medium","day1_critical":"N","effort_hours":40},{"title":"Benchmark against past deals","priority":"Low","day1_critical":"N","effort_hours":4},{"title":"Review with buyer and seller CFOs","priority":"High","day1_critical":"N","effort_hours":35}]},{"name":"Day-1 scope definition","description":"Decide what must work on the morning after close.","priority":"Medium","tasks":[{"title":"Draft Day-1 must-have list","priority":"Medium","day1_critical":"N","effort_hours":38},{"title":"Validate with business process owners","priority":"Medium","day1_critical":"N","effort_hours":6},{"title":"Freeze Day-1 scope","priority":"Low","day1_critical":"N","effort_hours":15},{"title":"Set change-control process","priority":"Low","day1_critical":"N","effort_hours":40}]},{"name":"TSA service catalogue","description":"Define services the seller will provide after close, with price and term.","priority":"Medium","tasks":[{"title":"List candidate TSA services","priority":"High","day1_critical":"N","effort_hours":23},{"title":"Link services to applications and assets","priority":"Low","day1_critical":"N","effort_hours":13},{"title":"Draft service descriptions","priority":"High","day1_critical":"N","effort_hours":31},{"title":"Price services with seller finance","priority":"Medium","day1_critical":"N","effort_hours":38}]},{"name":"Buyer-seller cost sharing scenarios","description":"Compare beneficiary-pays, even split, usage-based and avoided-cost credit bases.","priority":"Low","tasks":[{"title":"Itemise shared cost lines","priority":"Low","day1_critical":"N","effort_hours":25},{"title":"Model four sharing bases","priority":"Medium","day1_critical":"N","effort_hours":7},{"title":"Prepare control-board options paper","priority":"High","day1_critical":"N","effort_hours":6},{"title":"Record agreed basis per item","priority":"Medium","day1_critical":"N","effort_hours":29}]}]}', 'signing,template,tsa exit', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 5, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0003', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Stage Template', 'TSA exit', 'Financial Services & Payments', 'Day-1 Readiness', 'Day-1 Readiness playbook - Payments TSA exit (anonymised)', 'The business runs the morning after close: systems, access, network, licences, rehearsal. Worked well on a closed tsa exit in Financial Services & Payments.', '{"stage":{"name":"Day-1 Readiness","description":"The business runs the morning after close: systems, access, network, licences, rehearsal.","gate_criteria":"Go decision signed by partner and client; Day-1 issue log opened."},"activities":[{"name":"Network circuit separation (11 sites)","description":"Circuits, IP ranges and firewall rules split per site; long lead times tracked.","priority":"High","tasks":[{"title":"Order new circuits from carriers","priority":"High","day1_critical":"Y","effort_hours":20},{"title":"Track 90-180 day circuit lead times","priority":"Medium","day1_critical":"N","effort_hours":8},{"title":"Plan IP re-addressing","priority":"Medium","day1_critical":"N","effort_hours":13},{"title":"Update firewall rules","priority":"Low","day1_critical":"N","effort_hours":8},{"title":"Cut over pilot site","priority":"Critical","day1_critical":"Y","effort_hours":24},{"title":"Cut over remaining sites","priority":"High","day1_critical":"N","effort_hours":26}]},{"name":"Licence and contract assignments","description":"Vendor consents and contract novations needed for Day-1.","priority":"High","tasks":[{"title":"Send consent requests to vendors","priority":"Critical","day1_critical":"Y","effort_hours":5},{"title":"Chase pending vendor consents","priority":"High","day1_critical":"Y","effort_hours":29},{"title":"Novate support contracts","priority":"Medium","day1_critical":"N","effort_hours":18},{"title":"Confirm licence keys for new entity","priority":"Critical","day1_critical":"Y","effort_hours":39},{"title":"Record consent status per licence","priority":"High","day1_critical":"Y","effort_hours":30}]},{"name":"Identity and mailbox cut-over (4,200 mailboxes)","description":"Accounts, groups and mailboxes moved so people can log in and email on Day-1.","priority":"High","tasks":[{"title":"Extract identity and group data","priority":"Medium","day1_critical":"N","effort_hours":18},{"title":"Map users to new tenant","priority":"High","day1_critical":"N","effort_hours":25},{"title":"Pilot mailbox migration","priority":"Medium","day1_critical":"N","effort_hours":37},{"title":"Run bulk mailbox migration","priority":"High","day1_critical":"Y","effort_hours":16},{"title":"Validate privileged accounts","priority":"Critical","day1_critical":"Y","effort_hours":19},{"title":"Hypercare for login issues","priority":"Medium","day1_critical":"N","effort_hours":11}]},{"name":"Mock Day-1 rehearsal","description":"Dress rehearsal of the cut-over weekend.","priority":"High","tasks":[{"title":"Write cut-over runbook","priority":"Low","day1_critical":"N","effort_hours":30},{"title":"Run mock cut-over","priority":"High","day1_critical":"Y","effort_hours":26},{"title":"Log rehearsal issues","priority":"High","day1_critical":"N","effort_hours":16},{"title":"Fix rehearsal issues","priority":"Medium","day1_critical":"N","effort_hours":13},{"title":"Go / no-go recommendation to control board","priority":"Medium","day1_critical":"N","effort_hours":39}]}]}', 'day-1 readiness,template,tsa exit', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 6, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0004', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Stage Template', 'TSA exit', 'Financial Services & Payments', 'TSA Exit', 'TSA Exit playbook - Payments TSA exit (anonymised)', 'Exit every TSA service on time and at least cost. Worked well on a closed tsa exit in Financial Services & Payments.', '{"stage":{"name":"TSA Exit","description":"Exit every TSA service on time and at least cost.","gate_criteria":"All services exited or formally extended; stranded-cost plan approved."},"activities":[{"name":"Stranded cost actions","description":"Help the seller remove cost left behind after exit.","priority":"High","tasks":[{"title":"List stranded cost items","priority":"Low","day1_critical":"N","effort_hours":14},{"title":"Agree reduction actions","priority":"Medium","day1_critical":"N","effort_hours":39},{"title":"Track savings delivered","priority":"High","day1_critical":"N","effort_hours":6}]},{"name":"TSA service exit sequencing","description":"Compare exit orders by fees saved, dependencies and delivery risk.","priority":"Medium","tasks":[{"title":"Load TSA service register","priority":"Medium","day1_critical":"N","effort_hours":34},{"title":"Map dependencies between services","priority":"Medium","day1_critical":"N","effort_hours":17},{"title":"Model three exit sequences","priority":"Medium","day1_critical":"N","effort_hours":40},{"title":"Present sequence options to control board","priority":"High","day1_critical":"N","effort_hours":20},{"title":"Lock agreed exit order","priority":"Low","day1_critical":"N","effort_hours":25}]},{"name":"Service exit sign-off","description":"Formal sign-off that each TSA service is exited and billing stops.","priority":"Medium","tasks":[{"title":"Collect exit evidence per service","priority":"Medium","day1_critical":"N","effort_hours":31},{"title":"Client sign-off per service","priority":"Low","day1_critical":"N","effort_hours":36},{"title":"Seller billing stop confirmation","priority":"Low","day1_critical":"N","effort_hours":18},{"title":"Update TSA register","priority":"Medium","day1_critical":"N","effort_hours":27}]}]}', 'tsa exit,template,tsa exit', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 9, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0005', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Stage Template', 'TSA exit', 'Financial Services & Payments', 'Close-out', 'Close-out playbook - Payments TSA exit (anonymised)', 'Close cleanly and turn the deal into reusable knowledge. Worked well on a closed tsa exit in Financial Services & Payments.', '{"stage":{"name":"Close-out","description":"Close cleanly and turn the deal into reusable knowledge.","gate_criteria":"Knowledge manager approval; DPO confirms consent and retention."},"activities":[{"name":"Final status and benefits report","description":"Outcome versus plan for the client.","priority":"High","tasks":[{"title":"Compile final status","priority":"Medium","day1_critical":"N","effort_hours":27},{"title":"Calculate benefits delivered","priority":"Low","day1_critical":"N","effort_hours":33},{"title":"Partner review","priority":"Medium","day1_critical":"N","effort_hours":28},{"title":"Issue report to client","priority":"High","day1_critical":"N","effort_hours":34}]},{"name":"Close-out metrics capture","description":"TSA term, extensions, one-time cost, Day-1 incidents for benchmarks.","priority":"High","tasks":[{"title":"Capture TSA term and extensions","priority":"Medium","day1_critical":"N","effort_hours":18},{"title":"Capture one-time cost","priority":"Medium","day1_critical":"N","effort_hours":27},{"title":"Capture Day-1 incidents","priority":"Medium","day1_critical":"N","effort_hours":38},{"title":"Validate metrics with manager","priority":"High","day1_critical":"N","effort_hours":23}]},{"name":"Lessons learned and knowledge contribution","description":"Redacted, consent-checked learnings for the knowledge hub.","priority":"Medium","tasks":[{"title":"Run lessons-learned workshop","priority":"Low","day1_critical":"N","effort_hours":7},{"title":"Draft lessons learned","priority":"Medium","day1_critical":"N","effort_hours":12},{"title":"Confirm client reuse consent","priority":"Medium","day1_critical":"N","effort_hours":22},{"title":"Redact client identifiers","priority":"Low","day1_critical":"N","effort_hours":21}]},{"name":"Archive and access removal","description":"Retention, archive and removal of access.","priority":"Medium","tasks":[{"title":"Archive engagement files","priority":"Medium","day1_critical":"N","effort_hours":5},{"title":"Apply retention schedule","priority":"Medium","day1_critical":"N","effort_hours":18},{"title":"Remove team access","priority":"High","day1_critical":"N","effort_hours":22},{"title":"DPO confirmation","priority":"Low","day1_critical":"N","effort_hours":39}]}]}', 'close-out,template,tsa exit', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 5, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0006', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Activity Template', 'TSA exit', 'Financial Services & Payments', 'Diligence', 'IT run-cost baseline', 'Establish current IT run cost of the business being separated.', '{"activity":{"name":"IT run-cost baseline","description":"Establish current IT run cost of the business being separated.","priority":"Low"},"tasks":[{"title":"Collect IT cost allocations","priority":"Medium","day1_critical":"N"},{"title":"Split shared cost by usage","priority":"Medium","day1_critical":"N"},{"title":"Estimate standalone run cost","priority":"Low","day1_critical":"N"},{"title":"Review cost model with finance","priority":"Low","day1_critical":"N"}]}', 'activity,template', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 8, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0007', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Lesson', 'TSA exit', 'Financial Services & Payments', 'Day-1 Readiness', 'Start circuit orders in Signing, not Day-1', 'Network circuits took 120-170 days. Orders placed after signing put two sites at risk of missing Day-1. Place carrier orders as soon as site scope is known.', NULL, 'network,lead-time,day-1', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 7, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0008', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Lesson', 'TSA exit', 'Financial Services & Payments', 'TSA Exit', 'Sequence low-dependency TSA services first', 'Exiting low-dependency services (email, service desk) two months early saved fees and freed the team for the hard ERP exit. Model exit order before the TSA is signed.', NULL, 'tsa,sequencing,cost', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 7, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
