INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0017', 'PRJ-0010', 'Semiconductor Day-1 carve-out (anonymised)', 'Lesson', 'Day-1 readiness', 'Semiconductors & High-Tech', 'Day-1 Readiness', 'Start circuit orders in Signing, not Day-1', 'Network circuits took 120-170 days. Orders placed after signing put two sites at risk of missing Day-1. Place carrier orders as soon as site scope is known.', NULL, 'network,lead-time,day-1', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 1, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
