INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0022', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Stage Template', 'Spin-off', 'Healthcare & Life Sciences', 'Signing', 'Signing playbook - Healthcare spin-off (anonymised)', 'Turn diligence into separation terms: blueprint, TSA catalogue, cost sharing, Day-1 scope. Worked well on a closed spin-off in Healthcare & Life Sciences.', TO_CLOB('{"stage":{"name":"Signing","description":"Turn diligence into separation terms: blueprint, TSA catalogue, cost sharing, Day-1 scope.","gate_criteria":"Deal signed; Day-1 scope and TSA catalogue baselined."},"activities":[{"name":"Separation blueprint and dispositions","description":"Assign each application one end state: clone & go, stand-up, consolidate, extract & sunset, commercial agreement.","priority":"High","tasks":[{"title":"Agree disposition criteria with client","priority":"Medium","day1_critical":"N","effort_hours":25},{"title":"Score applications against criteria","priority":"Low","day1_critical":"N","effort_hours":34},{"title":"Draft recommended dispositions","priority":"Medium","day1_critical":"N","effort_hours":38},{"title":"Workshop dispositions with client CIO","priority":"Medium","day1_critical":"N","effort_hours":37},{"title":"Record approvals and overrides","priority":"Medium","day1_critical":"N","effort_hours":14},{"title":"Publish blueprint v1","priority":"Low","day1_critical":"N","effort_hours":19}]},{"name":"TSA service catalogue","description":"Define services the seller will provide after close, with price and term.","priority":"Medium","tasks":[{"title":"List candidate TSA services","priority":"Medium","day1_critical":"N","effort_hours":24},{"title":"Link services to applications and assets","priority":"Low","day1_critical":"N","effort_hours":24},{"title":"Draft service descriptions","priority":"Low","day1_critical":"N","effort_hours":6},{"title":"Price services with seller finance","priority":"Medium","day1_critical":"N","effort_hours":30},{"title":"Set extension terms","priority":"Medium","day1_critical":"N","effort_hours":33},{"title":"Hand catalogue to legal for SPA schedules","priority":"Low","day1_critical":"N","effort_hours":12}]},{"name":"One-time and stranded cost estimate","description":"Cost to separate and seller cost left behind.","priority":"Low","tasks":[{"title":"Build one-time cost model","priority":"Medium","day1_critical":"N","effort_hours":34},{"title":"Estimate stranded IT cost","priority":"Medium","day1_critical":"N","effort_hours":21},{"title":"Benchmark against past deals","priority":"Medium","day1_critical":"N","effort_hours":35},{"title":"Review with buyer and seller CFOs","priority":"High","day1_critical":"N","effort_hours":36}]},{"name":"Buyer-seller cost sharing scenarios","description":"Compare beneficiary-pays, even split, usage-based and avoided-cost credit bases.","priority":"Medium","tasks":[{"title":"Itemise shared cost lines","priority":"Low","day1_critical":"N","effort_hours":10},{"title":"Model four sharing bases","priority":"Low","day1_critical":"N","effort_hours":5},{"title":"Prepare control-board options paper","priority":"High","day1_critical":"N","effort_hours":18},{"title":"Record agreed basis per item","priority":"Low","day1_critical":"N","effort_hours":8}]},{"name":"Day-1 scope definition","description":"Decide what must work on the morning after close.","priority":"High","ta') || TO_CLOB('sks":[{"title":"Draft Day-1 must-have list","priority":"Medium","day1_critical":"N","effort_hours":16},{"title":"Validate with business process owners","priority":"Medium","day1_critical":"N","effort_hours":18},{"title":"Freeze Day-1 scope","priority":"Medium","day1_critical":"N","effort_hours":37},{"title":"Set change-control process","priority":"Low","day1_critical":"N","effort_hours":20}]}]}'), 'signing,template,spin-off', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 0, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0023', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Stage Template', 'Spin-off', 'Healthcare & Life Sciences', 'Day-1 Readiness', 'Day-1 Readiness playbook - Healthcare spin-off (anonymised)', 'The business runs the morning after close: systems, access, network, licences, rehearsal. Worked well on a closed spin-off in Healthcare & Life Sciences.', '{"stage":{"name":"Day-1 Readiness","description":"The business runs the morning after close: systems, access, network, licences, rehearsal.","gate_criteria":"Go decision signed by partner and client; Day-1 issue log opened."},"activities":[{"name":"Day-1 critical system list (120 applications)","description":"Every system the business needs on Day-1, with owner and readiness state.","priority":"High","tasks":[{"title":"Confirm critical list with business","priority":"Critical","day1_critical":"Y","effort_hours":36},{"title":"Assign owner per critical system","priority":"High","day1_critical":"N","effort_hours":35},{"title":"Test access for critical systems","priority":"High","day1_critical":"Y","effort_hours":12},{"title":"Close open readiness gaps","priority":"Critical","day1_critical":"Y","effort_hours":30}]},{"name":"Licence and contract assignments","description":"Vendor consents and contract novations needed for Day-1.","priority":"High","tasks":[{"title":"Send consent requests to vendors","priority":"Critical","day1_critical":"Y","effort_hours":39},{"title":"Chase pending vendor consents","priority":"High","day1_critical":"Y","effort_hours":34},{"title":"Novate support contracts","priority":"Medium","day1_critical":"N","effort_hours":32},{"title":"Confirm licence keys for new entity","priority":"Low","day1_critical":"N","effort_hours":28},{"title":"Record consent status per licence","priority":"High","day1_critical":"N","effort_hours":10}]},{"name":"Identity and mailbox cut-over (3,100 mailboxes)","description":"Accounts, groups and mailboxes moved so people can log in and email on Day-1.","priority":"High","tasks":[{"title":"Extract identity and group data","priority":"High","day1_critical":"Y","effort_hours":14},{"title":"Map users to new tenant","priority":"High","day1_critical":"Y","effort_hours":14},{"title":"Pilot mailbox migration","priority":"Low","day1_critical":"N","effort_hours":39},{"title":"Run bulk mailbox migration","priority":"High","day1_critical":"Y","effort_hours":37},{"title":"Validate privileged accounts","priority":"High","day1_critical":"Y","effort_hours":31}]}]}', 'day-1 readiness,template,spin-off', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 6, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0024', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Stage Template', 'Spin-off', 'Healthcare & Life Sciences', 'TSA Exit', 'TSA Exit playbook - Healthcare spin-off (anonymised)', 'Exit every TSA service on time and at least cost. Worked well on a closed spin-off in Healthcare & Life Sciences.', TO_CLOB('{"stage":{"name":"TSA Exit","description":"Exit every TSA service on time and at least cost.","gate_criteria":"All services exited or formally extended; stranded-cost plan approved."},"activities":[{"name":"Service exit sign-off","description":"Formal sign-off that each TSA service is exited and billing stops.","priority":"High","tasks":[{"title":"Collect exit evidence per service","priority":"High","day1_critical":"N","effort_hours":15},{"title":"Client sign-off per service","priority":"Low","day1_critical":"N","effort_hours":31},{"title":"Seller billing stop confirmation","priority":"Medium","day1_critical":"N","effort_hours":30},{"title":"Update TSA register","priority":"Medium","day1_critical":"N","effort_hours":14}]},{"name":"TSA service exit sequencing","description":"Compare exit orders by fees saved, dependencies and delivery risk.","priority":"Low","tasks":[{"title":"Load TSA service register","priority":"Low","day1_critical":"N","effort_hours":28},{"title":"Map dependencies between services","priority":"Medium","day1_critical":"N","effort_hours":28},{"title":"Model three exit sequences","priority":"Medium","day1_critical":"N","effort_hours":25},{"title":"Present sequence options to control board","priority":"High","day1_critical":"N","effort_hours":27},{"title":"Lock agreed exit order","priority":"Medium","day1_critical":"N","effort_hours":37}]},{"name":"Application migration waves","description":"Move applications off seller infrastructure in planned waves.","priority":"Medium","tasks":[{"title":"Group applications into waves","priority":"Low","day1_critical":"N","effort_hours":31},{"title":"Plan wave 1 cut-over","priority":"Medium","day1_critical":"N","effort_hours":30},{"title":"Execute wave 1","priority":"High","day1_critical":"N","effort_hours":21},{"title":"Plan wave 2 cut-over","priority":"Medium","day1_critical":"N","effort_hours":31},{"title":"Execute wave 2","priority":"Medium","day1_critical":"N","effort_hours":5},{"title":"Decommission seller access","priority":"Medium","day1_critical":"N","effort_hours":18}]},{"name":"Stranded cost actions","description":"Help the seller remove cost left behind after exit.","priority":"Low","tasks":[{"title":"List stranded cost items","priority":"Medium","day1_critical":"N","effort_hours":15},{"title":"Agree reduction actions","priority":"Medium","day1_critical":"N","effort_hours":21},{"title":"Track savings delivered","priority":"High","day1_critical":"N","effort_hours":20}]},{"name":"Extension risk and cost watch","description":"Early warning on services likely to need an extension (median uplift about 20%).","priority":"High","tasks":[{"title":"Flag services at risk of late exit","priority":"Medium","day1_critical":"N","effort_hours":21},{"title":"Cost extension scenarios","priority":"Low","day1_critical":"N","effort_hours":32},{"title":"Agree mitigation with owners","priority":"Medium","day1_critical":"N","effort_hours":35},{"title":"Notify seller 60 days before exit","priority":"Medium') || TO_CLOB('","day1_critical":"N","effort_hours":34}]}]}'), 'tsa exit,template,spin-off', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 1, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0025', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Stage Template', 'Spin-off', 'Healthcare & Life Sciences', 'Close-out', 'Close-out playbook - Healthcare spin-off (anonymised)', 'Close cleanly and turn the deal into reusable knowledge. Worked well on a closed spin-off in Healthcare & Life Sciences.', '{"stage":{"name":"Close-out","description":"Close cleanly and turn the deal into reusable knowledge.","gate_criteria":"Knowledge manager approval; DPO confirms consent and retention."},"activities":[{"name":"Archive and access removal","description":"Retention, archive and removal of access.","priority":"High","tasks":[{"title":"Archive engagement files","priority":"High","day1_critical":"N","effort_hours":39},{"title":"Apply retention schedule","priority":"High","day1_critical":"N","effort_hours":31},{"title":"Remove team access","priority":"High","day1_critical":"N","effort_hours":19},{"title":"DPO confirmation","priority":"Medium","day1_critical":"N","effort_hours":13}]},{"name":"Lessons learned and knowledge contribution","description":"Redacted, consent-checked learnings for the knowledge hub.","priority":"Medium","tasks":[{"title":"Run lessons-learned workshop","priority":"Medium","day1_critical":"N","effort_hours":29},{"title":"Draft lessons learned","priority":"Medium","day1_critical":"N","effort_hours":7},{"title":"Confirm client reuse consent","priority":"High","day1_critical":"N","effort_hours":30},{"title":"Redact client identifiers","priority":"High","day1_critical":"N","effort_hours":30},{"title":"Submit to knowledge manager","priority":"Medium","day1_critical":"N","effort_hours":7}]},{"name":"Final status and benefits report","description":"Outcome versus plan for the client.","priority":"Medium","tasks":[{"title":"Compile final status","priority":"Medium","day1_critical":"N","effort_hours":31},{"title":"Calculate benefits delivered","priority":"Medium","day1_critical":"N","effort_hours":36},{"title":"Partner review","priority":"Medium","day1_critical":"N","effort_hours":4},{"title":"Issue report to client","priority":"High","day1_critical":"N","effort_hours":34}]}]}', 'close-out,template,spin-off', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 3, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0026', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Activity Template', 'Spin-off', 'Healthcare & Life Sciences', 'Diligence', 'Cyber and licence red flags', 'Security gaps and non-transferable licences that change price or plan.', '{"activity":{"name":"Cyber and licence red flags","description":"Security gaps and non-transferable licences that change price or plan.","priority":"High"},"tasks":[{"title":"Review licence assignment clauses","priority":"Medium","day1_critical":"N"},{"title":"List licences needing vendor consent","priority":"Medium","day1_critical":"N"},{"title":"Check privileged access model","priority":"Low","day1_critical":"N"},{"title":"Assess cyber posture gaps","priority":"Low","day1_critical":"N"},{"title":"Brief partner on red flags","priority":"High","day1_critical":"N"}]}', 'activity,template', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 0, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0027', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Lesson', 'Spin-off', 'Healthcare & Life Sciences', 'Day-1 Readiness', 'Start circuit orders in Signing, not Day-1', 'Network circuits took 120-170 days. Orders placed after signing put two sites at risk of missing Day-1. Place carrier orders as soon as site scope is known.', NULL, 'network,lead-time,day-1', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 2, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0028', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Lesson', 'Spin-off', 'Healthcare & Life Sciences', 'TSA Exit', 'Sequence low-dependency TSA services first', 'Exiting low-dependency services (email, service desk) two months early saved fees and freed the team for the hard ERP exit. Model exit order before the TSA is signed.', NULL, 'tsa,sequencing,cost', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 1, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0029', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Metric', 'Spin-off', 'Healthcare & Life Sciences', 'Close-out', 'Close-out metrics - Healthcare spin-off (anonymised)', 'Standard close-out metrics for benchmarks.', '{"tsa_term_months":14,"extensions":2,"extension_uplift_pct":20,"one_time_cost_pct_revenue":"2.0","day1_incidents":4,"apps_in_scope":120}', 'metrics,benchmark', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 4, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0030', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Risk', 'Spin-off', 'Healthcare & Life Sciences', 'Signing', 'Licence consents found late', 'Several vendor licences needed consent to assign. Found during Day-1 prep, they forced short-term TSA extensions. Check assignment clauses during diligence.', NULL, 'licences,consent,risk', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 6, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0031', 'PRJ-0010', 'Semiconductor Day-1 carve-out (anonymised)', 'Lesson', 'Day-1 readiness', 'Semiconductors & High-Tech', 'Signing', 'Split shared Day-1 equipment by measured usage, not 50 / 50', 'Shared test equipment and design-tool licences were split by measured buyer usage (about 70%). Agreeing the usage numbers early stopped a month of back-and-forth at the control board.', NULL, 'funding,cost-sharing,usage', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 2, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0032', 'PRJ-0009', 'Payments TSA exit (anonymised)', 'Lesson', 'TSA exit', 'Financial Services & Payments', 'Day-1 Readiness', 'Bridge loan covered Day-1 spend until the seller contribution landed', 'The seller contribution under the SPA was paid only after close. A 9-month bridge loan covered Day-1 spend; agree drawdown dates and the refinancing plan before signing.', NULL, 'funding,bridge,spa', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 2, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0033', 'PRJ-0011', 'Healthcare spin-off (anonymised)', 'Risk', 'Spin-off', 'Healthcare & Life Sciences', 'TSA Exit', 'SPA seller cap used up before the TSA exit', 'Day-1 costs used up the seller cap in the SPA, leaving TSA-exit cost with the buyer. Track the seller share against the cap every month and negotiate a holdback release tied to exit milestones.', NULL, 'funding,spa-cap,escrow', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-14 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 2, TO_TIMESTAMP('2026-10-04 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0034', 'PRJ-0007', 'Retail logistics TSA exit (anonymised)', 'Lesson', 'TSA exit', 'Consumer & Retail', 'TSA Exit', 'Warehouse system cut-over needs a peak-season freeze window', 'Retail logistics cut-overs must avoid festive peak. Plan exits for low-volume weeks and agree the freeze window early.', NULL, 'pending', 'Granted', 'Pending Review', NULL, NULL, 0, TO_TIMESTAMP('2026-11-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0004', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0035', 'PRJ-0007', 'Retail logistics TSA exit (anonymised)', 'Activity Template', 'TSA exit', 'Consumer & Retail', 'TSA Exit', 'Warehouse management system migration wave', 'Activity template: WMS migration with parallel run and rollback plan.', '{"activity":{"name":"Warehouse management system migration wave","description":"Activity template: WMS migration with parallel run and rollback plan.","priority":"High"},"tasks":[{"title":"Agree freeze window","priority":"High"},{"title":"Parallel run for two weeks","priority":"High"},{"title":"Rollback rehearsal","priority":"Medium"},{"title":"Decommission old WMS access","priority":"Medium"}]}', 'pending', 'Granted', 'Pending Review', NULL, NULL, 0, TO_TIMESTAMP('2026-11-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0004', NULL, NULL, 'N');
